INSERT INTO xoops_stories (storyid, uid, title, created, published, expired, hostname, nohtml, nosmiley, hometext, bodytext, counter, topicid, ihome, notifypub, story_type, topicdisplay, topicalign, comments) VALUES (1, 1, 'Unreal Tournament 2004 Ships', 1079430900, 1079431500, 0, '24.95.13.7', 0, 0, 'Unreal Tournament 2004 is in stores as of this morning. The regular edition comes on six CDs, and there is also a DVD special edition with a Logitech headset in the box if you want to pay a little extra for voice chat.
INSERT INTO xoops_stories (storyid, uid, title, created, published, expired, hostname, nohtml, nosmiley, hometext, bodytext, counter, topicid, ihome, notifypub, story_type, topicdisplay, topicalign, comments) VALUES (2, 1, 'Far Cry and Condition Zero Hit Shelves', 1080065400, 1080066000, 0, '24.95.13.7', 0, 0, 'Two big PC releases landed today. Crytek''s Far Cry is out from Ubisoft, and Valve finally shipped Counter-Strike: Condition Zero after more than two years and three different developers.
INSERT INTO xoops_stories (storyid, uid, title, created, published, expired, hostname, nohtml, nosmiley, hometext, bodytext, counter, topicid, ihome, notifypub, story_type, topicdisplay, topicalign, comments) VALUES (3, 4, 'LAN Party Report: 48 Hours, Dial-Up Jokes, and One Dead Switch', 1080424440, 1080425040, 0, '24.95.13.7', 0, 0, 'Our regular weekend LAN crew burned through a stack of CD-Rs installing patches and somehow still found time for a Counter-Strike tournament. 31 people showed up, which is a new record for the church basement.
INSERT INTO xoops_stories (storyid, uid, title, created, published, expired, hostname, nohtml, nosmiley, hometext, bodytext, counter, topicid, ihome, notifypub, story_type, topicdisplay, topicalign, comments) VALUES (4, 1, 'Half-Life 2 Delay Talk: What We Know So Far', 1080639720, 1080640320, 0, '24.95.13.7', 0, 0, 'Six months after the game missed its September 30 date, there is still no firm release date for Half-Life 2. We round up the latest statements from Valve and Vivendi and weigh in on why nobody should pencil in a date just yet.
INSERT INTO xoops_stories (storyid, uid, title, created, published, expired, hostname, nohtml, nosmiley, hometext, bodytext, counter, topicid, ihome, notifypub, story_type, topicdisplay, topicalign, comments) VALUES (5, 1, 'World of Warcraft Beta Invites: Who Got In?', 1080916020, 1080916620, 0, '24.95.13.7', 0, 0, 'Blizzard sent out another round of closed beta invitations for World of Warcraft this week, and at least three of our forum regulars got the email. The beta is still under NDA, so do not expect screenshots from them.
INSERT INTO xoops_stories (storyid, uid, title, created, published, expired, hostname, nohtml, nosmiley, hometext, bodytext, counter, topicid, ihome, notifypub, story_type, topicdisplay, topicalign, comments) VALUES (6, 1, 'Our Thoughts on the Doom 3 Tech Demo', 1081108860, 1081109460, 0, '24.95.13.7', 0, 0, 'A few of us from the Nexus staff made the trip out to see id Software''s Doom 3 running live. The build on display was clearly a vertical slice rather than anything close to final, but the engine work is already the main story.
INSERT INTO xoops_xoopscomments (com_id, com_pid, com_rootid, com_modid, com_itemid, com_icon, com_created, com_modified, com_uid, com_ip, com_title, com_text, com_sig, com_status, com_exparams, dohtml, dosmiley, doxcode, doimage, dobr) VALUES (1, 0, 1, (SELECT mid FROM xoops_modules WHERE dirname='news'), 6, '', 1081112580, 1081112580, 5, '24.95.40.2', 'Re: Our Thoughts on the Doom 3 Tech Demo', 'If the lighting is even half as good as you''re describing I don''t care what my framerate looks like, I''m buying a new card for this.', 0, 2, '', 0, 1, 1, 1, 1);
INSERT INTO xoops_xoopscomments (com_id, com_pid, com_rootid, com_modid, com_itemid, com_icon, com_created, com_modified, com_uid, com_ip, com_title, com_text, com_sig, com_status, com_exparams, dohtml, dosmiley, doxcode, doimage, dobr) VALUES (2, 0, 2, (SELECT mid FROM xoops_modules WHERE dirname='news'), 6, '', 1081154820, 1081154820, 3, '24.95.40.2', 'Re: Our Thoughts on the Doom 3 Tech Demo', 'Did anyone ask them about multiplayer? Every preview I''ve read only talks about the single player corridors, kind of worried it''s going to be a solo-only game.', 0, 2, '', 0, 1, 1, 1, 1);
INSERT INTO xoops_xoopscomments (com_id, com_pid, com_rootid, com_modid, com_itemid, com_icon, com_created, com_modified, com_uid, com_ip, com_title, com_text, com_sig, com_status, com_exparams, dohtml, dosmiley, doxcode, doimage, dobr) VALUES (3, 0, 3, (SELECT mid FROM xoops_modules WHERE dirname='news'), 4, '', 1080648960, 1080648960, 6, '24.95.40.2', 'Re: Half-Life 2 Delay Talk', 'Christmas. Calling it now.', 0, 2, '', 0, 1, 1, 1, 1);
INSERT INTO xoops_xoopscomments (com_id, com_pid, com_rootid, com_modid, com_itemid, com_icon, com_created, com_modified, com_uid, com_ip, com_title, com_text, com_sig, com_status, com_exparams, dohtml, dosmiley, doxcode, doimage, dobr) VALUES (4, 0, 4, (SELECT mid FROM xoops_modules WHERE dirname='news'), 2, '', 1080078000, 1080078000, 11, '24.95.40.2', 'Re: Far Cry and Condition Zero Hit Shelves', 'Picked up CZ on the way home. The bots are better than half the people on our server :)', 0, 2, '', 0, 1, 1, 1, 1);
INSERT INTO xoops_bb_categories (cat_id, cat_title, cat_order) VALUES (1, 'Gaming', '1');
INSERT INTO xoops_bb_categories (cat_id, cat_title, cat_order) VALUES (2, 'Nexus Community', '2');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (1, 0, 1, 1, 1081116900, 2, '24.95.2.1', 'Doom 3 tech demo impressions', 0, 0, 'icon2.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (1, 'Read the front page write-up. Anybody else seen footage of the new build? The shadows look unreal but I''m worried about what it''ll take to run it.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (2, 1, 1, 1, 1081118460, 5, '24.95.5.1', 'Re: Doom 3 tech demo impressions', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (2, 'id always says it scales. Quake 3 ran fine on my old TNT2, so I''m not panicking yet.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (3, 1, 1, 1, 1081123920, 4, '24.95.4.1', 'Re: Doom 3 tech demo impressions', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (3, 'Quake 3 was a different time. Carmack has been saying a GeForce 3 is the minimum for a while now.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (4, 1, 1, 1, 1081155120, 3, '24.95.3.1', 'Re: Doom 3 tech demo impressions', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (4, 'I just want to know if there''s real multiplayer. Four players max is what I keep reading.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (5, 1, 1, 1, 1081199100, 1, '24.95.1.1', 'Re: Doom 3 tech demo impressions', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (5, 'We asked, they would not say anything about multiplayer. Expect more once E3 rolls around.');
INSERT INTO xoops_bb_topics (topic_id, topic_title, topic_poster, topic_time, topic_views, topic_replies, topic_last_post_id, forum_id, topic_status, topic_sticky) VALUES (1, 'Doom 3 tech demo impressions', 2, 1081199100, 312, 4, 5, 1, 0, 0);
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (6, 0, 2, 1, 1080241320, 4, '24.95.4.2', 'Far Cry - what are you running it on?', 0, 0, 'icon3.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (6, 'Got it Tuesday. Athlon XP 2500+, 512MB, Radeon 9700 Pro. Runs fine on high at 1024x768, a bit choppy on the big outdoor levels.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (7, 6, 2, 1, 1080247440, 6, '24.95.6.2', 'Re: Far Cry - what are you running it on?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (7, 'P4 2.4, GeForce4 Ti 4200. Medium settings and it still looks better than anything else I own.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (8, 6, 2, 1, 1080307200, 11, '24.95.11.2', 'Re: Far Cry - what are you running it on?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (8, 'Same card as Dave, the water on medium is still amazing. Those mercenaries hear everything though.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (9, 6, 2, 1, 1080381900, 10, '24.95.10.2', 'Re: Far Cry - what are you running it on?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (9, 'Quicksave would be nice. Lost half an hour to a checkpoint last night.');
INSERT INTO xoops_bb_topics (topic_id, topic_title, topic_poster, topic_time, topic_views, topic_replies, topic_last_post_id, forum_id, topic_status, topic_sticky) VALUES (2, 'Far Cry - what are you running it on?', 4, 1080381900, 241, 3, 9, 1, 0, 0);
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (10, 0, 3, 1, 1079739000, 8, '24.95.8.3', 'UT2004 Onslaught is the best thing since CTF', 0, 0, 'icon4.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (10, 'Played Onslaught until 3am. Torlan with a full server is chaos in the best way.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (11, 10, 3, 1, 1079781240, 2, '24.95.2.3', 'Re: UT2004 Onslaught is the best thing since CTF', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (11, 'The Manta is broken. I love it.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (12, 10, 3, 1, 1079887620, 12, '24.95.12.3', 'Re: UT2004 Onslaught is the best thing since CTF', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (12, 'Anyone running a server? I''d play on a Nexus one.');
INSERT INTO xoops_bb_topics (topic_id, topic_title, topic_poster, topic_time, topic_views, topic_replies, topic_last_post_id, forum_id, topic_status, topic_sticky) VALUES (3, 'UT2004 Onslaught is the best thing since CTF', 8, 1079887620, 158, 2, 12, 1, 0, 0);
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (13, 0, 4, 2, 1079126280, 7, '24.95.7.4', 'Ninja Gaiden is brutal', 0, 0, 'icon5.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (13, 'Two weeks in and I''m stuck on the first boss. Is this game even fair?');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (14, 13, 4, 2, 1079170800, 9, '24.95.9.4', 'Re: Ninja Gaiden is brutal', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (14, 'It''s fair, it just doesn''t care about your feelings. Block more and stop button mashing.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (15, 13, 4, 2, 1079277720, 10, '24.95.10.4', 'Re: Ninja Gaiden is brutal', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (15, 'Beat Murai on my 12th try. Best feeling all year.');
INSERT INTO xoops_bb_topics (topic_id, topic_title, topic_poster, topic_time, topic_views, topic_replies, topic_last_post_id, forum_id, topic_status, topic_sticky) VALUES (4, 'Ninja Gaiden is brutal', 7, 1079277720, 133, 2, 15, 2, 0, 0);
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (16, 0, 5, 2, 1080579960, 5, '24.95.5.5', 'PSP or Nintendo DS?', 0, 0, 'icon6.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (16, 'Sony says the PSP is out this year in Japan. Nintendo has the DS with two screens. Which one are you getting?');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (17, 16, 5, 2, 1080588660, 3, '24.95.3.5', 'Re: PSP or Nintendo DS?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (17, 'Whichever one has the better RPGs. Probably both, my wallet hates me.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (18, 16, 5, 2, 1080634320, 7, '24.95.7.5', 'Re: PSP or Nintendo DS?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (18, 'Nintendo always wins handhelds. My Game Boy Advance SP goes everywhere with me.');
INSERT INTO xoops_bb_topics (topic_id, topic_title, topic_poster, topic_time, topic_views, topic_replies, topic_last_post_id, forum_id, topic_status, topic_sticky) VALUES (5, 'PSP or Nintendo DS?', 5, 1080634320, 187, 2, 18, 2, 0, 0);
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (19, 0, 6, 3, 1080918120, 3, '24.95.3.6', 'WoW beta invites thread', 0, 0, 'icon7.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (19, 'Post here if you got an invite. I got mine on Wednesday!');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (20, 19, 6, 3, 1080922500, 2, '24.95.2.6', 'Re: WoW beta invites thread', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (20, 'Nothing here. Filled out the survey twice.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (21, 19, 6, 3, 1080931200, 6, '24.95.6.6', 'Re: WoW beta invites thread', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (21, 'Got one. Can''t say anything, but it''s worth the wait.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (22, 19, 6, 3, 1080988020, 4, '24.95.4.6', 'Re: WoW beta invites thread', 0, 0, 'icon1.gif', 1);
