INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (24, 0, 7, 3, 1078776900, 10, '24.95.10.7', 'Anyone still playing Star Wars Galaxies?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (24, 'Still logging in on Bria. The Jedi grind is brutal but my creature handler is having fun.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (25, 24, 7, 3, 1078857000, 12, '24.95.12.7', 'Re: Anyone still playing Star Wars Galaxies?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (25, 'Quit after the first three months, too many bugs. Might go back once they fix the space stuff.');
