INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (26, 0, 8, 4, 1080763200, 4, '24.95.4.8', 'April LAN - sign up here', 0, 0, 'icon2.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (26, 'April LAN is Saturday the 24th, same place. 32 seats, bring your own cable and power strip. Reply here to get on the list.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (27, 26, 8, 4, 1080763920, 2, '24.95.2.8', 'Re: April LAN - sign up here', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (27, 'In. Bringing the spare 19 inch monitor.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (28, 26, 8, 4, 1080811980, 8, '24.95.8.8', 'Re: April LAN - sign up here', 0, 0, 'icon1.gif', 1);
