INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (30, 0, 9, 4, 1080488640, 4, '24.95.4.9', 'March LAN photos', 0, 0, 'icon3.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (30, 'Photos are up on my site. 31 people, one dead switch, zero sleep.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (31, 30, 9, 4, 1080494400, 5, '24.95.5.9', 'Re: March LAN photos', 0, 0, 'icon1.gif', 1);
