INSERT INTO xoops_bb_topics (topic_id, topic_title, topic_poster, topic_time, topic_views, topic_replies, topic_last_post_id, forum_id, topic_status, topic_sticky) VALUES (9, 'March LAN photos', 4, 1080494400, 204, 1, 31, 4, 0, 0);
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (32, 0, 10, 5, 1080843720, 6, '24.95.6.10', 'Radeon 9800 Pro vs GeForce FX 5900 for Doom 3?', 0, 0, 'icon4.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (32, 'Upgrading before Doom 3 and HL2. 9800 Pro or FX 5900? Both around $300 right now.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (33, 32, 10, 5, 1080846300, 11, '24.95.11.10', 'Re: Radeon 9800 Pro vs GeForce FX 5900 for Doom 3?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (33, '9800 Pro. The FX cards choke on DX9 stuff, look at the HL2 benchmarks from last fall.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (34, 32, 10, 5, 1080855000, 2, '24.95.2.10', 'Re: Radeon 9800 Pro vs GeForce FX 5900 for Doom 3?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (34, 'Doom 3 is OpenGL though, and nVidia does better there. If Doom 3 is all you care about, get the FX.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (35, 32, 10, 5, 1080897000, 1, '24.95.1.10', 'Re: Radeon 9800 Pro vs GeForce FX 5900 for Doom 3?', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (35, 'Wait for the new cards both companies are showing this spring if you can. Prices on these will drop.');
INSERT INTO xoops_bb_topics (topic_id, topic_title, topic_poster, topic_time, topic_views, topic_replies, topic_last_post_id, forum_id, topic_status, topic_sticky) VALUES (10, 'Radeon 9800 Pro vs GeForce FX 5900 for Doom 3?', 6, 1080897000, 377, 3, 35, 5, 0, 0);
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (36, 0, 11, 5, 1079877720, 12, '24.95.12.11', 'Catalyst 4.3 broke my CS', 0, 0, 'icon5.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (36, 'Updated to Catalyst 4.3 and now Counter-Strike crashes on map change. Anyone else?');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (37, 36, 11, 5, 1079883000, 8, '24.95.8.11', 'Re: Catalyst 4.3 broke my CS', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (37, 'Roll back to 4.2 and run the driver cleaner first. Fixed it for me.');
INSERT INTO xoops_bb_topics (topic_id, topic_title, topic_poster, topic_time, topic_views, topic_replies, topic_last_post_id, forum_id, topic_status, topic_sticky) VALUES (11, 'Catalyst 4.3 broke my CS', 12, 1079883000, 88, 1, 37, 5, 0, 0);
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (38, 0, 12, 6, 1076775600, 1, '24.95.1.12', 'Welcome to the new Nexus (XOOPS 2)', 0, 0, 'icon6.gif', 1);
