INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (39, 38, 12, 6, 1076781780, 3, '24.95.3.12', 'Re: Welcome to the new Nexus (XOOPS 2)', 0, 0, 'icon1.gif', 1);
INSERT INTO xoops_bb_posts_text (post_id, post_text) VALUES (39, 'Looks good! My avatar came over fine.');
INSERT INTO xoops_bb_posts (post_id, pid, topic_id, forum_id, post_time, uid, poster_ip, subject, nohtml, nosmiley, icon, attachsig) VALUES (40, 38, 12, 6, 1076845620, 2, '24.95.2.12', 'Re: Welcome to the new Nexus (XOOPS 2)', 0, 0, 'icon1.gif', 1);
